import * as Axiom from "alchemy/Axiom";
import * as Output from "alchemy/Output";
import { retain } from "alchemy/RemovalPolicy";
import * as Effect from "effect/Effect";
import { commonPracticeDashboardDefinitions } from "./dashboards";
import type { CommonPracticeDashboardDatasets } from "./dashboards/types";

export { CommonPracticeObservability } from "../stacks/observability";

/**
 * Site owns the three physical datasets; Common Practice owns only its scoped token and
 * dashboards. Cloudflare's export destinations use the token, so it is retained
 * like the dashboards: removing the declaration or destroying this stack must not cut
 * off production telemetry. A replaced token leaves its old generation in
 * Axiom for deliberate revocation.
 */
export const declareCommonPracticeAxiomResources = Effect.fn(
  "Axiom.declareCommonPracticeResources",
)(function* (datasets: CommonPracticeDashboardDatasets) {
  const ingest = yield* Axiom.ApiToken("CommonPracticeTelemetryIngest", {
    name: "common-practice-telemetry-ingest",
    description: "Ingest Common Practice Effect telemetry only; renamed 3 October 2026",
    datasetCapabilities: {
      [datasets.logsDataset]: { ingest: ["create"] },
      [datasets.tracesDataset]: { ingest: ["create"] },
      [datasets.metricsDataset]: { ingest: ["create"] },
    },
  }).pipe(retain());

  const definitions = commonPracticeDashboardDefinitions(datasets);
  yield* Effect.forEach(
    definitions,
    Effect.fnUntraced(function* (definition) {
      yield* Axiom.Dashboard(definition.logicalId, {
        // These declarations create the five Common Practice link IDs.
        // The former dashboard objects are retired by the approved hard cutover.
        uid: definition.uid,
        // Alchemy's public Chart model is readonly while its provider input
        // currently requires mutable SDK arrays. Alchemy resolves the typed
        // document at plan time without changing its JSON value.
        dashboard: Output.asOutput(definition.dashboard).as<Axiom.DashboardProps["dashboard"]>(),
        overwrite: true,
      }).pipe(retain());
    }),
    { concurrency: 1, discard: true },
  );

  return { ingest, dashboardCount: definitions.length };
});
