import * as Axiom from "alchemy/Axiom";
import * as Cloudflare from "alchemy/Cloudflare";
import { Stack } from "alchemy/Stack";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
import { productionStage } from "./addresses";
import { deploymentSecrets } from "../secrets";

/**
 * The providers and state both telemetry stacks (`common-practice-observability` and
 * `common-practice-trace-export`) run with. Both provider Layers read HttpClient from
 * StackServices (alchemy/Stack.ts), so neither depends on the other's output. This is
 * Alchemy's documented composition, and the diagnostic sees a dependency that is not one.
 */
export const telemetryStackProps = {
  // @effect-diagnostics-next-line layerMergeAllWithDependencies:off
  providers: Layer.mergeAll(Cloudflare.providers(), Axiom.providers()),
  state: Cloudflare.state(),
  secrets: deploymentSecrets,
};

/** Both telemetry stacks are production-only: the live Website depends on their resources. */
export const requireProductionStage = Effect.gen(function* () {
  const stack = yield* Stack;
  // oxlint-disable-next-line effect/no-schema-decoder-outside-ingress -- Alchemy supplies this raw CLI stage at the stack entrypoint.
  yield* Schema.decodeUnknownEffect(Schema.Literal(productionStage))(stack.stage).pipe(
    Effect.mapError((cause) => new Config.ConfigError(cause)),
  );
});
