import * as Alchemy from "alchemy";
import * as Effect from "effect/Effect";
import { identity } from "effect/Function";
import * as Option from "effect/Option";
import { commonPracticeTraceExportStackName } from "./addresses";
import { StageReferenceMissing } from "./errors";

/** Common Practice's Cloudflare trace destination (`alchemy.trace.run.ts`). */
export class CommonPracticeTraceExport extends Alchemy.Stack<
  CommonPracticeTraceExport,
  { readonly destinationName: string; readonly logsDestinationName: string }
>()(commonPracticeTraceExportStackName) {}

/** Production's persisted `common-practice-trace-export` outputs, read from any stage. */
export const commonPracticeTraceExportProduction: Effect.Effect<CommonPracticeTraceExport> =
  Effect.suspend(() =>
    Option.match(Option.fromNullishOr(CommonPracticeTraceExport.stage.production), {
      onNone: () =>
        Effect.die(new StageReferenceMissing({ stack: commonPracticeTraceExportStackName })),
      onSome: identity,
    }),
  );
