/**
 * Stack and stage names of every Alchemy stack Common Practice reads. Each value appears
 * once; stack classes, references and entry points import these names instead
 * of repeating stack or stage strings.
 */
export const commonPracticeObservabilityStackName = "common-practice-observability";
export const commonPracticeTraceExportStackName = "common-practice-trace-export";

/** The only stage of Common Practice's shared, production-owned telemetry stacks. */
export const productionStage = "production";

export const commonPracticeObservabilityProduction = {
  stack: commonPracticeObservabilityStackName,
  stage: productionStage,
} as const;

/**
 * Site's stack owns the shared Axiom datasets. Common Practice only reads their persisted
 * attributes through resource references; it never declares or adopts them.
 */
export const siteProduction = { stack: "CooperCorbettSiteCloudflare", stage: "prod" } as const;
