import * as Axiom from "alchemy/Axiom";
import * as Cloudflare from "alchemy/Cloudflare";
import * as Output from "alchemy/Output";
import { retain } from "alchemy/RemovalPolicy";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import { commonPracticeObservabilityProduction, siteProduction } from "../stacks/addresses";

export { CommonPracticeTraceExport } from "../stacks/trace-export";

/**
 * The account destination is Common Practice-owned; only Common Practice Workers opt in to it.
 * Production Workers and Previews depend on it, so a removed declaration or
 * a stack destroy leaves the Cloudflare destination in place.
 */
export const declareCommonPracticeTraceDestination = Effect.fn(
  "Cloudflare.declareCommonPracticeTraceDestination",
)(function* () {
  const token = yield* Axiom.ApiToken.ref(
    "CommonPracticeTelemetryIngest",
    commonPracticeObservabilityProduction,
  );
  const traces = yield* Axiom.Dataset.ref("SiteProdTracesDataset", siteProduction);
  const configuration = {
    url: traces.otelTracesEndpoint,
    headers: {
      Authorization: token.token.pipe(
        // oxlint-disable-next-line effect/no-native-array-methods -- Alchemy Output.map resolves a deferred secret, not an Array.
        Output.map((secret) => `Bearer ${Redacted.value(secret)}`),
      ),
      "X-Axiom-Dataset": traces.name,
    },
    logpushDataset: "opentelemetry-traces" as const,
    enabled: true,
  };
  return yield* Cloudflare.Workers.ObservabilityDestination("CommonPracticeAxiomTraces", {
    ...configuration,
    name: "common-practice-axiom-traces",
  }).pipe(retain());
});

/** Logs use a separate destination; the same retained token is held by Cloudflare. */
export const declareCommonPracticeLogDestination = Effect.fn(
  "Cloudflare.declareCommonPracticeLogDestination",
)(function* () {
  const token = yield* Axiom.ApiToken.ref(
    "CommonPracticeTelemetryIngest",
    commonPracticeObservabilityProduction,
  );
  const logs = yield* Axiom.Dataset.ref("SiteProdLogsDataset", siteProduction);
  return yield* Cloudflare.Workers.ObservabilityDestination("CommonPracticeAxiomLogs", {
    name: "common-practice-axiom-logs",
    url: logs.otelLogsEndpoint,
    headers: {
      // oxlint-disable-next-line effect/no-native-array-methods -- Alchemy Output.map resolves a deferred secret, not an Array.
      Authorization: token.token.pipe(Output.map((secret) => `Bearer ${Redacted.value(secret)}`)),
      "X-Axiom-Dataset": logs.name,
    },
    logpushDataset: "opentelemetry-logs",
    enabled: true,
  }).pipe(retain());
});

