322	import { projectName, requestEventName } from "../../observability/names";
323	import type {
324	  CommonPracticeDashboardDatasets,
325	  SharedLogsDatasetName,
326	  SharedTracesDatasetName,
327	} from "./types";
328	
329	/**
330	 * Readers for the fields the queries share. A missing column reads as empty text or
331	 * zero, so a record or span without it still counts. Custom span attributes are map
332	 * keys under `attributes.custom`; a dotted path is an Axiom error.
333	 */
334	const commonPracticeTextColumn = (field: string): string =>
335	  `tostring(column_ifexists('${field}', ''))`;
336	const commonPracticeNumberColumn = (field: string): string =>
337	  `toint(column_ifexists('${field}', 0))`;
338	const commonPracticeCustomText = (key: string): string =>
339	  `tostring(['attributes.custom']['${key}'])`;
340	const commonPracticeCustomNumber = (key: string): string =>
341	  `toint(['attributes.custom']['${key}'])`;
342	
343	/** Current Website Workers and historical parent-named Preview spans; exclude APIs. */
344	const commonPracticeWorkerName = `tostring(column_ifexists('faas.name', column_ifexists('resource.faas.name', '')))`;
345	const commonPracticeWorkerScope = `(WorkerName in ('daw-production', 'preview-daw-production', 'common-practice-production', 'preview-common-practice-production') or WorkerName matches regex '^common-practice-(preview|integration|pr-[1-9][0-9]{0,6})$')`;
346	
347	/** Every dashboard query starts with this parameter. An empty value selects every stage. */
348	export const commonPracticeStageParameter = `declare query_parameters (stage:string = "");`;
349	
350	/**
351	 * Request records contain only the bounded categories emitted by the Effect observer.
352	 * `Result` sorts each request into one class, so a chart can keep 404 probes apart
353	 * from real errors: `Errors` are 5xx responses and requests that did not complete.
354	 */
355	export const commonPracticeRequestSource = (dataset: SharedLogsDatasetName): string =>
356	  `['${dataset}']
357	| extend Entry=parse_json(tostring(body))
358	| where tostring(Entry.message) == '${requestEventName}'
359	| extend Request=Entry.annotations
360	| where tostring(Request.project) == '${projectName}' and tostring(Request.worker) == 'website'
361	| extend RecordStage=tostring(Request.stage)
362	| where stage == '' or RecordStage == stage
363	| extend Surface=tostring(Request.surface), RouteFamily=tostring(Request.routeFamily), Method=tostring(Request.method), Outcome=tostring(Request.outcome), StatusGroup=tostring(Request.statusGroup), Status=toint(Request.status), TrafficCategory=tostring(Request.trafficCategory), AiBot=tostring(Request.aiBot)
364	| extend Result=case(Outcome in ('failed', 'cancelled') or StatusGroup == '5xx', 'Errors', Status == 404, 'Not found', StatusGroup == '4xx', 'Rejected (other 4xx)', 'Success')`;
365	
366	export const commonPracticeRequestQuery = (dataset: SharedLogsDatasetName): string =>
367	  `${commonPracticeStageParameter}
368	${commonPracticeRequestSource(dataset)}`;
369	
370	/**
371	 * The stage filter for spans that carry the request URL. Production traffic arrives
372	 * on the apex only (the workers.dev address is off); every Preview stage
373	 * (`preview`, `integration`, `pr-<number>`) has a `common-practice-<stage>` host.
374	 * The former `<stage>-common-practice-production` hosts remain readable.
375	 */
376	const commonPracticeTraceStageFilter = `| extend PreviewStage=extract('^https://(?:common-practice-)?(preview|integration|pr-[1-9][0-9]{0,6})(?:-(?:common-practice|daw)-production)?[.]coopercorbett[.]workers[.]dev/', 1, RequestUrl)
377	| where stage == '' or (stage == 'production' and (RequestUrl startswith 'https://departmentofagenticwork.com/' or RequestUrl startswith 'https://withcommonpractice.com/')) or (stage != 'production' and PreviewStage == stage)`;
378	
379	/**
380	 * Stage-owned Workers carry distinct names. The request host also separates
381	 * stages for historical Preview spans that used their parent Worker's name.
382	 */
383	const commonPracticeTraceSource = (dataset: SharedTracesDatasetName): string =>
384	  `['${dataset}']
385	| extend WorkerName=${commonPracticeWorkerName}, RequestUrl=${commonPracticeTextColumn("attributes.url.full")}
386	| where ${commonPracticeWorkerScope}
387	${commonPracticeTraceStageFilter}`;
388	
389	export const commonPracticeTraceQuery = (dataset: SharedTracesDatasetName): string =>
390	  `${commonPracticeStageParameter}
391	${commonPracticeTraceSource(dataset)}`;
392	
393	/**
394	 * One row per Worker invocation: Cloudflare's native root span (`GET`, `POST`, ...).
395	 * The runtime times it, so its `cpu_time_ms` is real CPU time, unlike Effect span
396	 * durations, which read the frozen Workers clock. Its own duration is not latency: it
397	 * can include `waitUntil` work, such as backend analytics. Custom
398	 * attributes are read as `['attributes.custom']['key']`; a dotted path is an error.
399	 * `Path` is the URL path only, never the query string.
400	 */
401	export const commonPracticeTraceInvocationSource = (dataset: SharedTracesDatasetName): string =>
402	  `${commonPracticeTraceSource(dataset)}
403	| where isempty(parent_span_id)
404	| extend CpuMs=${commonPracticeCustomNumber("cpu_time_ms")}, Outcome=${commonPracticeCustomText("cloudflare.outcome")}, Status=${commonPracticeNumberColumn("attributes.http.response.status_code")}, Path=${commonPracticeTextColumn("attributes.url.path")}
405	| extend StatusGroup=case(Status >= 100 and Status < 200, '1xx', Status >= 200 and Status < 300, '2xx', Status >= 300 and Status < 400, '3xx', Status >= 400 and Status < 500, '4xx', Status >= 500 and Status < 600, '5xx', 'unknown')`;
406	
407	export const commonPracticeTraceInvocationQuery = (dataset: SharedTracesDatasetName): string =>
408	  `${commonPracticeStageParameter}
409	${commonPracticeTraceInvocationSource(dataset)}`;
410	
411	/** Correlate automatic root spans with checked request logs; no Website custom spans. */
412	export const commonPracticeTraceRequestQuery = ({
413	  logsDataset,
414	  tracesDataset,
415	}: Pick<CommonPracticeDashboardDatasets, "logsDataset" | "tracesDataset">): string =>
416	  `${commonPracticeStageParameter}
417	${commonPracticeTraceInvocationSource(tracesDataset)}
418	| join kind=leftouter (
419	  ${commonPracticeRequestSource(logsDataset)}
420	  | where isnotempty(trace_id)
421	  | summarize RequestSeq=max(toint(Request.requestSeq)), RouteFamilies=make_set(RouteFamily, 1) by trace_id
422	  | project trace_id, RequestSeq, RouteFamily=tostring(RouteFamilies[0])
423	) on trace_id
424	| project _time, trace_id, CpuMs, Status, Path, Outcome, RequestSeq, RouteFamily
425	| extend Start=case(RequestSeq == 1, 'Cold start', RequestSeq > 1, 'Warm', 'Unlabelled')`;
426	
427	/**
428	 * The tail of a count-and-share table: one row per value of the column, sorted by
429	 * count, with its share of all rows and a bar whose length is proportional to the
430	 * count (zero baseline). The largest row has 12 blocks, short enough for a phone.
431	 * The bar is counted in eighths of a block, and no row is shorter than one eighth,
432	 * so a small row still shows. One pass: the grouped rows are folded into one row
433	 * so each row can read the total and the largest count.
434	 */
435	export const commonPracticeCountShareTable = (column: string, heading: string): string =>
436	  `| summarize Requests=count() by ${column}
437	| summarize Rows=make_list(pack('Key', ${column}, 'Requests', Requests)), Total=sum(Requests), Largest=max(Requests)
438	| mv-expand Rows
439	| extend Requests=toint(Rows['Requests'])
440	| extend Eighths=case(round(96.0 * Requests / Largest, 0) < 1, 1, toint(round(96.0 * Requests / Largest, 0)))
441	| extend Full=toint(floor(Eighths / 8.0))
442	| extend Part=Eighths - 8 * Full
443	| project ['${heading}']=tostring(Rows['Key']), Requests, ['Share (%)']=round(100.0 * Requests / Total, 1), Bar=strcat(substring('████████████', 0, Full), case(Part == 0, '', substring('▏▎▍▌▋▊▉', Part - 1, 1)))
444	| sort by Requests desc`;
