      // content-only change deploys a new Website version.
      // Hash the Website and the workspace packages it bundles. Native
      // gitignore excludes do not reach `../` paths, so name them here;
      // otherwise the hash follows linked node_modules into the package store.
      memo: {
        exclude: [
          "**/node_modules/**",
          "**/dist/**",
          "**/.alchemy/**",
          "**/.output/**",
          "**/.tanstack/**",
          "**/.turbo/**",
          "**/.wrangler/**",
          "**/.vitest/**",
          "**/.env",
          "**/.env.*",
          "public/og/**",
          "../../packages/**/node_modules/**",
          "../../packages/**/dist/**",
          "../../packages/**/.source/**",
          "../../packages/**/.turbo/**",
          "../../packages/**/*.tsbuildinfo",
        ],
        include: ["**/*", "../../packages/**"],
        lockfile: true,
      },
      // The Website's platform records can include caller URLs independently
      // of its fixed application reporter. Keep them off.
      observability: {
        enabled: false,
        headSamplingRate: 0,
        logs: {
          enabled: false,
          headSamplingRate: 0,
          invocationLogs: false,
          persist: false,
        },
        traces: { enabled: false, headSamplingRate: 0, persist: false },
      },
      rootDir: "apps/web",
    };
  })
) {}

export const declareNativeAppsStack = Effect.gen(function* () {
  const stage = yield* checkedStage(yield* Stage);
  const zone =
    stage === "prod"
      ? Option.some(
          yield* Zone("TaxKitProductionZone", {
            name: "taxkit.dev",
            paused: false,
            type: "full",
          }).pipe(adopt(true), retain())
        )
      : Option.none<Zone>();
  if (Option.isSome(zone)) {
    // Preserve the DNS settings independently read on 7 October. This does
    // not change registrar, mail or verification records.
    yield* ZoneDnsSettings("TaxKitProductionDnsSettings", {
      flattenAllCnames: false,
      foundationDns: false,
      multiProvider: false,
      nameservers: { type: "cloudflare.standard" },
      nsTtl: 86_400,
      secondaryOverrides: false,
      zoneId: zone.value.zoneId,
      zoneMode: "standard",
    }).pipe(retain());
    yield* Effect.forEach(productionZoneSettings, (setting) =>
      Setting(setting.resource, {
        settingId: setting.settingId,
        value: setting.value,
        zoneId: zone.value.zoneId,
      }).pipe(retain())
    );
    // Cloudflare Registrar publishes the DS record when signing starts.
    yield* Dnssec("TaxKitProductionDnssec", {
      status: "active",
      zoneId: zone.value.zoneId,
    }).pipe(retain());
    yield* BotManagement("TaxKitProductionBotManagement", {
      ...productionBotPolicy,
      zoneId: zone.value.zoneId,
    }).pipe(retain());
  }
  return yield* Effect.gen(function* () {
    const api = yield* TaxKitApiWorker;
    const website = yield* TaxKitWebsite;
    return { apiUrl: api.url, websiteUrl: website.url };
  }).pipe(
    Effect.provide(NativeApiHostLive),
    Effect.provideService(NativeProductionZone, zone)
  );
});
import * as Doppler from "alchemy/Doppler";
import * as Secrets from "alchemy/Secrets";
import type { SecretsContext } from "alchemy/Secrets";
import type { StackSecrets } from "alchemy/Stack";
import { Config, ConfigProvider, Effect, Layer, Match, Schema } from "effect";

import { AppStage, PreviewStage } from "./stage.js";

/** The TaxKit Doppler config that holds a stage's values. */
export const dopplerConfig = (stage: AppStage) =>
  Match.value(stage).pipe(
    Match.when("prod", () => "prd" as const),
    Match.when(Schema.is(PreviewStage), () => "stg_preview" as const),
    Match.orElse(() => "dev" as const)
  );

// The stage is Alchemy input. An invalid stage fails before any provider asks
// for credentials or reads a secret.
export const checkedStage = (stage: string) =>
  Schema.decodeUnknownEffect(AppStage)(stage).pipe(
    Effect.mapError(
      () =>
        new Config.ConfigError(
          new ConfigProvider.SourceError({
            message: "The TaxKit stage name is not supported",
          })
        )
    )
  );

/**
 * Native sources for the app stack, in precedence order: Doppler for the
 * stage, the calculator rate namespace, an ignored `.env`, and never the shell.
 * Doppler `prd`, `stg_preview` and `dev` hold each stage's Cloudflare values.
 */
export const deploymentSecrets = (({ stage }: SecretsContext) => [
  Layer.unwrap(
    checkedStage(stage).pipe(
      Effect.map(
        (checked) =>
          Doppler.Secrets({ config: dopplerConfig(checked), project: "taxkit" })
            .layer
      )
    )
  ),
  // Each deployed stage owns its own rate-limit counters. Production uses
  // 10078 and Preview appends its pull-request number.
  ConfigProvider.layerAdd(
    checkedStage(stage).pipe(
      Effect.map((checked) =>
        Match.value(checked).pipe(
          Match.when("prod", () =>
            ConfigProvider.fromUnknown({ CALCULATOR_RATE_NAMESPACE: "10078" })
          ),
          Match.when(Schema.is(PreviewStage), (preview) =>
            ConfigProvider.fromUnknown({
              CALCULATOR_RATE_NAMESPACE: `10078${preview.slice(3)}`,
            })
          ),
          Match.orElse(() => ConfigProvider.fromUnknown({}))
        )
      )
    ),
    { asPrimary: true }
  ),
  Secrets.DotEnv().layer,
  Secrets.ProcessEnv({ disabled: true }),
]) satisfies StackSecrets;
import * as Schema from "effect/Schema";

// Pull-request Preview stages share one Doppler config and own one stage each.
export const PreviewStage = Schema.String.check(
  Schema.isPattern(/^pr-[1-9]\d{0,6}$/u)
).pipe(Schema.brand("taxkit/PreviewStage"));

// Local development uses its own stage and local state, never cloud state.
export const LocalStage = Schema.String.check(
  Schema.isPattern(/^dev_[a-z0-9]+(?:[-_a-z0-9]+)*$/iu)
).pipe(Schema.brand("taxkit/LocalStage"));

export const DeploymentStage = Schema.Union([
  Schema.Literal("prod"),
  PreviewStage,
]);
export type DeploymentStage = typeof DeploymentStage.Type;

export const AppStage = Schema.Union([DeploymentStage, LocalStage]);
export type AppStage = typeof AppStage.Type;
